fn shift_letters(s: Str, n: Int) -> Str {
    let chars = chars(s)
    let shifted_chars = map(chars, |c| {
        let code = unwrap_or(unwrap_or(char_code(c), -1) + n, -1)
        if code < 97 || code > 122 { c } else { int_to_char(code) }
    })
    concat(shifted_chars)
}

