fn sieve(n: Int) -> Vec<Int> {
    let mut primes = vec()
    for i in range(2, n + 1) {
        primes = push(primes, i)
    }
    let mut i = 0
    while i < len(primes) {
        let p = primes[i]
        let j = i + 1
        while j < len(primes) {
            if primes[j] % p == 0 {
                primes = remove(primes, j)
            } else {
                j += 1
            }
        }
        i += 1
    }
    primes
}
